import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.x7b91k6X.js";const m=JSON.parse('{"title":"故障博物馆","description":"","frontmatter":{},"headers":[],"relativePath":"incidents/index.md","filePath":"incidents/index.md","lastUpdated":1793856207000}'),o={name:"incidents/index.md"};function c(i,t,s,n,h,l){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="故障博物馆" tabindex="-1">故障博物馆 <a class="header-anchor" href="#故障博物馆" aria-label="Permalink to &quot;故障博物馆&quot;">​</a></h1><blockquote><p>30 条真实线上症状，按「症状 → 假设树 → 定位动作 → 验证与排除 → 修复要点 → 关联章节」固定字段编排。 用途不是背答案，而是练习<strong>在信息不全时先列假设、再用工具证伪</strong>的排查顺序；每条都与正文知识点一一对应。</p></blockquote><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><ol><li><strong>先盖住「定位动作」</strong>：只读症状与假设树，自己写出“下一步查什么、用什么工具、期望看到什么”。</li><li><strong>再对照「验证与排除」</strong>：重点看它如何用一次观测排除一整类假设，而不是看结论。</li><li><strong>最后回正文</strong>：关联章节给出机制与正确写法；能解释机制，才算真正修好，而不是碰巧改对。</li><li>配合每章「精通判据」的「能兜底」维度：把修复要点改写成一份上线预案（监控信号 → 阈值 → 降级/回滚 → 恢复验证）。</li></ol><blockquote><p>工具行为以 Xcode 16 基线为准；标「待真机验证」的阈值/行为（如扩展内存上限、Jetsam 具体阈值）因设备与系统版本而异，需在目标机型复测。</p></blockquote><h2 id="分册与覆盖" tabindex="-1">分册与覆盖 <a class="header-anchor" href="#分册与覆盖" aria-label="Permalink to &quot;分册与覆盖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分册</th><th>条目</th><th>覆盖类目</th></tr></thead><tbody><tr><td><a href="./startup-perf">启动与性能</a></td><td>INC-01 ~ INC-05（5 条）</td><td>启动慢 3、卡顿 2</td></tr><tr><td><a href="./memory-crash">内存与崩溃</a></td><td>INC-06 ~ INC-11（6 条）</td><td>内存暴涨/OOM 3、崩溃 3</td></tr><tr><td><a href="./network-concurrency">网络与并发</a></td><td>INC-12 ~ INC-16（5 条）</td><td>网络 3、并发死锁 2</td></tr><tr><td><a href="./build-release">构建与发布</a></td><td>INC-17 ~ INC-22（6 条）</td><td>包体 2、构建/签名 2、灰度回滚 2</td></tr><tr><td><a href="./compliance-ecosystem">合规与生态</a></td><td>INC-23 ~ INC-30（8 条）</td><td>隐私合规 3、App 扩展 3、埋点 2</td></tr></tbody></table><h2 id="症状速查" tabindex="-1">症状速查 <a class="header-anchor" href="#症状速查" aria-label="Permalink to &quot;症状速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>症状一句话</th><th>首查工具</th><th>分册</th></tr></thead><tbody><tr><td>INC-01</td><td>冷启动白屏约 3 秒，热启动正常</td><td><code>DYLD_PRINT_STATISTICS</code> + Time Profiler</td><td><a href="./startup-perf">启动与性能</a></td></tr><tr><td>INC-02</td><td>首帧前卡住，<code>+load</code>/静态初始化耗时长</td><td>Time Profiler + signpost</td><td><a href="./startup-perf">启动与性能</a></td></tr><tr><td>INC-03</td><td>pre-main 阶段随动态库数量线性变慢</td><td><code>DYLD_PRINT_STATISTICS</code> + <code>otool -L</code></td><td><a href="./startup-perf">启动与性能</a></td></tr><tr><td>INC-04</td><td>列表滑动掉帧，帧耗时超预算</td><td>Instruments Core Animation / Hangs</td><td><a href="./startup-perf">启动与性能</a></td></tr><tr><td>INC-05</td><td>主线程同步 IO/网络导致界面无响应</td><td>System Trace + Time Profiler</td><td><a href="./startup-perf">启动与性能</a></td></tr><tr><td>INC-06</td><td>图片列表内存暴涨，被系统 jetsam 杀</td><td>Allocations + Xcode Organizer</td><td><a href="./memory-crash">内存与崩溃</a></td></tr><tr><td>INC-07</td><td>大图/大对象分配后常驻内存不降</td><td>Allocations + <code>vmmap</code></td><td><a href="./memory-crash">内存与崩溃</a></td></tr><tr><td>INC-08</td><td>页面反复进出后内存持续增长</td><td>Memory Graph + <code>leaks</code></td><td><a href="./memory-crash">内存与崩溃</a></td></tr><tr><td>INC-09</td><td>偶发 <code>EXC_BAD_ACCESS</code> 野指针崩溃</td><td>Zombies + <code>atos</code> 符号化</td><td><a href="./memory-crash">内存与崩溃</a></td></tr><tr><td>INC-10</td><td>强制解包/数组越界崩溃集中在发布版</td><td>崩溃栈 + 符号化</td><td><a href="./memory-crash">内存与崩溃</a></td></tr><tr><td>INC-11</td><td>KVO/通知移除后崩溃或线程相关崩溃</td><td>Zombies + 崩溃栈</td><td><a href="./memory-crash">内存与崩溃</a></td></tr><tr><td>INC-12</td><td>明文 HTTP 请求被 ATS 拦截</td><td><code>nscurl --ats-diagnostics</code></td><td><a href="./network-concurrency">网络与并发</a></td></tr><tr><td>INC-13</td><td>换证后全量请求失败，旧版本正常</td><td>抓包 + 证书链检查</td><td><a href="./network-concurrency">网络与并发</a></td></tr><tr><td>INC-14</td><td>弱网下请求堆积、超时后雪崩</td><td>URLSession 任务指标 + 日志</td><td><a href="./network-concurrency">网络与并发</a></td></tr><tr><td>INC-15</td><td>并发写共享状态出现丢更新/错乱</td><td>Thread Sanitizer</td><td><a href="./network-concurrency">网络与并发</a></td></tr><tr><td>INC-16</td><td>主线程同步等待异步回调导致卡死</td><td>System Trace + 主线程栈</td><td><a href="./network-concurrency">网络与并发</a></td></tr><tr><td>INC-17</td><td>包体超预算，资源占比异常</td><td>App Thinning Size Report</td><td><a href="./build-release">构建与发布</a></td></tr><tr><td>INC-18</td><td>重复符号警告，单例出现两份</td><td>链接日志 + <code>nm -m</code></td><td><a href="./build-release">构建与发布</a></td></tr><tr><td>INC-19</td><td>归档签名失败/描述文件不匹配</td><td><code>codesign</code> + <code>security find-identity</code></td><td><a href="./build-release">构建与发布</a></td></tr><tr><td>INC-20</td><td>CI 多机并发后签名状态混乱</td><td><code>security find-identity</code> + 构建日志</td><td><a href="./build-release">构建与发布</a></td></tr><tr><td>INC-21</td><td>灰度放量后崩溃率上升，需要回滚</td><td>MetricKit + 崩溃聚合</td><td><a href="./build-release">构建与发布</a></td></tr><tr><td>INC-22</td><td>Kill Switch 打开后线上仍未生效</td><td>Flag 评估日志 + 分桶校验</td><td><a href="./build-release">构建与发布</a></td></tr><tr><td>INC-23</td><td>隐私清单缺失/原因码错误被拒审</td><td>归档告警 + <code>plutil</code></td><td><a href="./compliance-ecosystem">合规与生态</a></td></tr><tr><td>INC-24</td><td>埋点里出现明文手机号/邮箱</td><td>埋点样本 + 脱敏日志</td><td><a href="./compliance-ecosystem">合规与生态</a></td></tr><tr><td>INC-25</td><td>权限用途说明缺失或过度申请</td><td><code>Info.plist</code> + 审核回复</td><td><a href="./compliance-ecosystem">合规与生态</a></td></tr><tr><td>INC-26</td><td>扩展运行中被系统杀死</td><td>崩溃/终止日志 + Organizer</td><td><a href="./compliance-ecosystem">合规与生态</a></td></tr><tr><td>INC-27</td><td>App Group 容器读写失败/缓存不一致</td><td>容器 URL 检查 + 日志</td><td><a href="./compliance-ecosystem">合规与生态</a></td></tr><tr><td>INC-28</td><td>Widget 不刷新或刷新预算耗尽</td><td>WidgetCenter + 系统日志</td><td><a href="./compliance-ecosystem">合规与生态</a></td></tr><tr><td>INC-29</td><td>退后台后埋点批量丢失</td><td>flush 日志 + 本地队列检查</td><td><a href="./compliance-ecosystem">合规与生态</a></td></tr><tr><td>INC-30</td><td>埋点 schema 漂移导致报表口径错</td><td>schema 校验日志 + 下游样本</td><td><a href="./compliance-ecosystem">合规与生态</a></td></tr></tbody></table><h2 id="与正文的映射" tabindex="-1">与正文的映射 <a class="header-anchor" href="#与正文的映射" aria-label="Permalink to &quot;与正文的映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类目</th><th>主要关联章节</th></tr></thead><tbody><tr><td>启动、卡顿、内存、渲染</td><td><a href="./../06-performance-security">第 6 章 性能优化与安全</a></td></tr><tr><td>并发、死锁、Sendable</td><td><a href="./../02-swift-advanced">第 2 章 Swift 高级特性</a></td></tr><tr><td>野指针、KVO、Block</td><td><a href="./../03-objc-runtime">第 3 章 Objective-C 与运行时</a></td></tr><tr><td>网络、持久化、生命周期</td><td><a href="./../05-apple-frameworks">第 5 章 iOS/macOS 框架</a></td></tr><tr><td>签名、公证、包体、隐私清单</td><td><a href="./../08-build-deployment">第 8 章 构建与部署</a></td></tr><tr><td>合规映射、企业集成</td><td><a href="./../10-enterprise-applications">第 10 章 企业级应用场景</a></td></tr><tr><td>扩展、App Group、Widget</td><td><a href="./../14-system-touchpoints">第 14 章 系统触点</a></td></tr><tr><td>埋点、灰度、回滚、MetricKit</td><td><a href="./../15-observability-ops">第 15 章 线上运营闭环</a></td></tr></tbody></table><h2 id="使用边界" tabindex="-1">使用边界 <a class="header-anchor" href="#使用边界" aria-label="Permalink to &quot;使用边界&quot;">​</a></h2><ul><li>⚠️ 博物馆给的是<strong>排查路径</strong>，不是唯一因果。同一症状可能由多个假设同时成立，必须用观测逐条证伪。</li><li>⚠️ 命令与工具名称随 Xcode 版本变化（如 Instruments 模板更名）；执行前先 <code>xcrun xctrace list templates</code> 确认本机可用模板。</li><li>✅ 修复后必须补一条回归验证（指标、日志或自动化用例），否则同类问题会在下一个版本复发。</li><li>❌ 不要用“重启/清缓存/再发一版”作为结论；没有定位到机制的动作，只是把问题推迟到下次。</li></ul>',13)])])}const p=d(o,[["render",c]]);export{m as __pageData,p as default};
